1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import type { SftpServer } from "../lib/sftp";
4	import { withServerSsh, exec, SETUP_TIMEOUT_MS } from "../lib/ssh-exec";
5	import {
6	  controlSpec,
7	  isGameFamily,
8	  isPowerAction,
9	  remoteLocateDir,
10	  runRcon,
11	  parsePlayers,
12	  computeNextRun,
13	  computeNextIntervalRun,
14	  shq,
15	  isSafeRemotePath,
16	  GAME_BACKUP_DIR,
17	  readGameLogs,
18	  logTrackingSpec,
19	  type GameControlSpec,
20	} from "../lib/game-control";
21	import type { Job } from "@prisma/client";
22	
23	/**
24	 * Game server control-panel worker handlers.
25	 *
26	 * Registered in worker/index.ts:
27	 *   GAME_POWER:  gamePower,
28	 *   GAME_BACKUP: gameBackup,
29	 * and `gameScheduleSweep()`, `playerTrackingSweep()` (RCON families) and
30	 * `logPlayerTrackingSweep()` (log-only families, e.g. Valheim) called on ~60s
31	 * timers.
32	 *
33	 * Everything runs over the platform's existing SSH (lib/ssh-exec withServerSsh —
34	 * host/port/root-password derived exactly like lib/sftp). Family/unit/path values
35	 * that reach the shell are compile-time constants or allowlisted (lib/game-control),
36	 * and the root password is never surfaced in an error (only a trimmed remote stderr
37	 * is, which never contains it).
38	 *
39	 * SANDBOX / no VM: handlers notify a simulation and touch nothing.
40	 */
41	
42	const CONTROL_FIELDS = {
43	  id: true,
44	  userId: true,
45	  hostname: true,
46	  status: true,
47	  rootPassword: true,
48	  rootPasswordEnc: true,
49	  sshPort: true,
50	  dedicatedIp: { select: { address: true } },
51	  node: { select: { publicIp: true } },
52	  osTemplate: { select: { family: true } },
53	  gamePlan: { select: { gameFamily: true } },
54	} as const;
55	
56	type ControlServer = {
57	  id: string;
58	  userId: string;
59	  hostname: string;
60	  status: string;
61	  rootPassword: string | null;
62	  rootPasswordEnc: string | null;
63	  sshPort: number | null;
64	  dedicatedIp: { address: string } | null;
65	  node: { publicIp: string } | null;
66	  osTemplate: { family: string | null };
67	  gamePlan: { gameFamily: string | null } | null;
68	};
69	
70	async function notify(userId: string, title: string, body?: string, href?: string) {
71	  try {
72	    await db.notification.create({ data: { userId, title, body, href } });
73	  } catch (e) {
74	    console.error("[game-control] notify failed", e);
75	  }
76	}
77	
78	function resolveSpec(server: ControlServer): GameControlSpec {
79	  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
80	  if (!isGameFamily(fam)) throw new Error("not a game server");
81	  const spec = controlSpec(fam);
82	  if (!spec) throw new Error("no control spec for family");
83	  return spec;
84	}
85	
86	/**
87	 * Build the remote unit-resolution + systemctl script. `hints`/`family` come from
88	 * the family's control spec (compile-time constants); `action` is one of the three
89	 * allowlisted verbs. Emits NXGP markers so a clean SSH exit is never mistaken for
90	 * a successful action (the same discipline as worker/game-update.ts).
91	 */
92	function powerScript(spec: GameControlSpec, action: string): string {
93	  const hints = spec.serviceHints.map(shq).join(" ");
94	  return [
95	    `unit=""`,
96	    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
97	    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
98	    `if [ -z "$unit" ]; then echo "NXGP:UNIT:NONE"; exit 0; fi`,
99	    `echo "NXGP:UNIT:$unit"`,
100	    `systemctl ${action} "$unit" >/dev/null 2>&1; echo "NXGP:RC:$?"`,
101	    `st=$(systemctl is-active "$unit" 2>/dev/null); echo "NXGP:STATE:${"$"}{st:-unknown}"`,
102	    `echo "NXGP:END"`,
103	  ].join("\n");
104	}
105	
106	/** GAME_POWER — start/stop/restart the game SERVICE (not the VM). */
107	export async function gamePower(job: Job): Promise<void> {
108	  if (!job.serverId) throw new Error("game power: missing serverId");
109	  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
110	  if (!server) throw new Error(`Server ${job.serverId} not found`);
111	  const spec = resolveSpec(server);
112	
113	  const p = (job.payload ?? {}) as { action?: string; announce?: boolean };
114	  const action = String(p.action ?? "");
115	  if (!isPowerAction(action)) throw new Error(`unsupported power action: ${action}`);
116	  const href = `/dashboard/servers/${server.id}?tab=manage`;
117	
118	  if (SANDBOX) {
119	    await notify(
120	      server.userId,
121	      `Game service ${action} (sandbox) on ${server.hostname}`,
122	      `Sandbox only — no VM was contacted; the ${spec.label} service was not ${action}ed.`,
123	      href
124	    );
125	    return;
126	  }
127	  if (server.status !== "RUNNING") throw new Error("game power: VM is not running");
128	
129	  // Optional pre-restart announce over RCON (best-effort; never fails the action).
130	  if (action === "restart" && p.announce && spec.rcon === "source") {
131	    try {
132	      await withServerSsh(server as SftpServer, (conn) =>
133	        runRcon(conn, spec, "say Server is restarting now (scheduled/maintenance).")
134	      );
135	    } catch (e) {
136	      console.error("[game-control] restart announce failed (continuing)", e);
137	    }
138	  }
139	
140	  const out = await withServerSsh(server as SftpServer, (conn) => exec(conn, powerScript(spec, action), SETUP_TIMEOUT_MS));
141	  const text = out.stdout;
142	  if (/NXGP:UNIT:NONE/.test(text)) {
143	    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `No game service unit was found on ${server.hostname}.`, href);
144	    throw new Error("game power: no service unit found");
145	  }
146	  const rc = Number(/NXGP:RC:(-?\d+)/.exec(text)?.[1] ?? "1");
147	  const state = /NXGP:STATE:(\w+)/.exec(text)?.[1] ?? "unknown";
148	  if (!/NXGP:END/.test(text) || rc !== 0) {
149	    await notify(server.userId, `Could not ${action} the ${spec.label} service`, `The ${action} did not complete on ${server.hostname} (state: ${state}).`, href);
150	    throw new Error(`game power: ${action} failed rc=${rc} state=${state}`);
151	  }
152	  await notify(
153	    server.userId,
154	    `${spec.label} service ${action}ed on ${server.hostname}`,
155	    action === "stop" ? "The game service was stopped." : `The game service was ${action}ed (now ${state}).`,
156	    href
157	  );
158	
159	  // Persist the real systemd state so the dashboard's status dot can reflect
160	  // it. GAME_POWER only ever touches the game SERVICE inside the VM, never
161	  // `Server.status` (the VM's own power state) — those are genuinely
162	  // different things, but the panel's "Online/Offline" label was reading
163	  // `Server.status` alone, so a customer who stopped just their game service
164	  // (VM still up) kept seeing "Online" no matter what they did. Found live
165	  // 2026-09-09 via a real customer confused why "Status: Online" never
166	  // changed after repeated stop/start attempts. `_serviceState` follows the
167	  // same gameConfig-internal-marker convention as `_real`/`_realOk`/
168	  // `_appliedAt` elsewhere in this file's siblings — no schema migration
169	  // needed for what's fundamentally transient, best-effort runtime state.
170	  try {
171	    const fresh = await db.server.findUnique({ where: { id: server.id }, select: { gameConfig: true } });
172	    const gameConfig = { ...(fresh?.gameConfig as Record<string, unknown> | null ?? {}), _serviceState: state };
173	    await db.server.update({ where: { id: server.id }, data: { gameConfig } });
174	  } catch (e) {
175	    console.error(`[game-control] could not persist _serviceState for ${server.hostname}`, e);
176	  }
177	}
178	
179	/** GAME_BACKUP — archive the world/save dir into a downloadable .tar.gz. */
180	export async function gameBackup(job: Job): Promise<void> {
181	  if (!job.serverId) throw new Error("game backup: missing serverId");
182	  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
183	  if (!server) throw new Error(`Server ${job.serverId} not found`);
184	  const spec = resolveSpec(server);
185	  const href = `/dashboard/servers/${server.id}?tab=manage`;
186	
187	  if (SANDBOX) {
188	    await notify(server.userId, `World backup created (sandbox) on ${server.hostname}`, `Sandbox only — no VM was contacted for the ${spec.label} world backup.`, href);
189	    return;
190	  }
191	  if (server.status !== "RUNNING") throw new Error("game backup: VM is not running");
192	
193	  const outcome = await withServerSsh(server as SftpServer, async (conn) => {
194	    const dir = await remoteLocateDir(conn, spec.dataRoots);
195	    if (!dir || !isSafeRemotePath(dir)) return { ok: false, msg: "Could not locate the world/save directory." };
196	    // Timestamped archive under the fixed backup dir. `parent`/`base` are derived
197	    // from the located (allowlisted) dir; every value interpolated is single-quoted.
198	    const ts = new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
199	    const archive = `${GAME_BACKUP_DIR}/${spec.family}-${ts}.tar.gz`;
200	    const parent = dir.replace(/\/[^/]+$/, "") || "/";
201	    const base = dir.replace(/^.*\//, "");
202	    const script =
203	      `mkdir -p ${shq(GAME_BACKUP_DIR)} && ` +
204	      `tar czf ${shq(archive)} -C ${shq(parent)} ${shq(base)} 2>&1 && ` +
205	      `stat -c '%s' ${shq(archive)}`;
206	    const r = await exec(conn, script, SETUP_TIMEOUT_MS);
207	    if (r.code !== 0) return { ok: false, msg: (r.stderr || r.stdout).trim().slice(0, 200) || "tar failed" };
208	    const size = Number(r.stdout.trim().split(/\r?\n/).pop());
209	    return { ok: true, archive, size: Number.isFinite(size) ? size : 0 };
210	  });
211	
212	  if (!outcome.ok) {
213	    await notify(server.userId, `World backup failed on ${server.hostname}`, outcome.msg, href);
214	    throw new Error(`game backup failed: ${outcome.msg}`);
215	  }
216	  const mb = ((outcome.size ?? 0) / (1024 * 1024)).toFixed(1);
217	  await notify(
218	    server.userId,
219	    `${spec.label} world backup ready on ${server.hostname}`,
220	    `Backed up your world (${mb} MB). Download it from the Manage → Worlds tab.`,
221	    href
222	  );
223	}
224	
225	/**
226	 * Fire due scheduled tasks. Selects enabled GameSchedule rows whose `nextRunAt`
227	 * has passed. For kind="restart", enqueues a GAME_POWER restart; for kind="command",
228	 * sends an RCON command directly. Advances `nextRunAt` appropriately (daily or
229	 * interval-based). Idempotent / safe on a timer.
230	 */
231	export async function gameScheduleSweep(): Promise<void> {
232	  const now = new Date();
233	  const due = await db.gameSchedule.findMany({
234	    where: { enabled: true, nextRunAt: { lte: now } },
235	    include: { server: { select: { id: true, status: true, osTemplate: { select: { family: true } }, gamePlan: { select: { gameFamily: true } } } } },
236	    take: 100,
237	  });
238	  if (due.length === 0) return;
239	
240	  for (const s of due) {
241	    // Always advance the clock first so a server that is down / mid-operation does
242	    // not cause the same row to be reselected every tick.
243	    const nextRunAt = s.intervalMinutes
244	      ? computeNextIntervalRun(s.intervalMinutes, now)
245	      : computeNextRun(s.hour, s.minute, now);
246	    await db.gameSchedule.update({ where: { id: s.id }, data: { lastRunAt: now, nextRunAt } }).catch(() => {});
247	
248	    const fam = s.server.gamePlan?.gameFamily ?? s.server.osTemplate?.family ?? null;
249	    if (!isGameFamily(fam)) continue;
250	    if (s.server.status !== "RUNNING") continue;
251	
252	    if (s.kind === "command" && s.command) {
253	      // Send RCON command directly (e.g. save-all, weather clear).
254	      const spec = controlSpec(fam);
255	      if (!spec || spec.rcon === "none") continue;
256	      // Load full server for SSH access.
257	      const server = await db.server.findUnique({ where: { id: s.server.id }, select: CONTROL_FIELDS });
258	      if (!server) continue;
259	      try {
260	        await withServerSsh(server as SftpServer, (conn) => runRcon(conn, spec, s.command!));
261	      } catch {
262	        // Best-effort: command schedules silently skip on failure.
263	      }
264	    } else {
265	      // Restart schedule: check for busy jobs first.
266	      const busy = await db.job.count({
267	        where: {
268	          serverId: s.server.id,
269	          status: { in: ["QUEUED", "RUNNING"] },
270	          type: { in: ["GAME_POWER", "GAME_BACKUP", "PROVISION", "REINSTALL", "DELETE", "RESIZE", "BACKUP_RESTORE"] as any },
271	        },
272	      });
273	      if (busy > 0) continue;
274	
275	      await db.job.create({ data: { type: "GAME_POWER", serverId: s.server.id, payload: { action: "restart", announce: s.announce } } });
276	    }
277	  }
278	}
