280	/**
281	 * Track player join/leave events by comparing the live RCON player list against
282	 * open PlayerSession rows (leftAt IS NULL). Runs every ~60s from the main loop.
283	 *
284	 * For each RUNNING game server with a gamePlan:
285	 *   - NEW players (in RCON but no open session) → create a PlayerSession
286	 *   - DEPARTED players (open session but not in RCON) → set leftAt = now()
287	 *   - STILL ONLINE → no-op
288	 *
289	 * Per-server try/catch so one unreachable VM never blocks the sweep.
290	 */
291	export async function playerTrackingSweep(): Promise<void> {
292	  if (SANDBOX) return;
293	
294	  const servers = await db.server.findMany({
295	    where: { status: "RUNNING", gamePlanId: { not: null } },
296	    select: CONTROL_FIELDS,
297	  });
298	
299	  const now = new Date();
300	
301	  for (const server of servers) {
302	    try {
303	      const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
304	      if (!isGameFamily(fam)) continue;
305	      const spec = controlSpec(fam);
306	      if (!spec || spec.rcon !== "source" || !spec.listCommand) continue;
307	
308	      // Get online players via RCON
309	      const res = await withServerSsh(server as SftpServer, (conn) =>
310	        runRcon(conn, spec, spec.listCommand!)
311	      );
312	      if (!res.ok) continue;
313	      const { players: onlinePlayers } = parsePlayers(spec.family, res.response);
314	      const onlineNames = new Set(onlinePlayers.map((p) => p.name.toLowerCase()));
315	
316	      // Get open sessions for this server
317	      const openSessions = await db.playerSession.findMany({
318	        where: { serverId: server.id, leftAt: null },
319	      });
320	      const sessionByName = new Map(
321	        openSessions.map((s) => [s.playerName.toLowerCase(), s])
322	      );
323	
324	      // NEW players: in RCON but no open session
325	      for (const p of onlinePlayers) {
326	        if (!sessionByName.has(p.name.toLowerCase())) {
327	          await db.playerSession.create({
328	            data: { serverId: server.id, playerName: p.name },
329	          });
330	        }
331	      }
332	
333	      // DEPARTED players: open session but not in RCON
334	      for (const session of openSessions) {
335	        if (!onlineNames.has(session.playerName.toLowerCase())) {
336	          await db.playerSession.update({
337	            where: { id: session.id },
338	            data: { leftAt: now },
339	          });
340	        }
341	      }
342	    } catch (e) {
343	      // Per-server: one failure must not break the sweep
344	      console.error(`[player-tracking] sweep failed for server ${server.id}`, e);
345	    }
346	  }
347	}
