349	/** Close the oldest still-open PlayerSession for `playerName` on `serverId`. */
350	async function closeOpenLogSession(serverId: string, playerName: string, inferred: boolean): Promise<void> {
351	  const open = await db.playerSession.findFirst({
352	    where: { serverId, playerName: { equals: playerName, mode: "insensitive" }, leftAt: null },
353	    orderBy: { joinedAt: "asc" },
354	  });
355	  if (open) {
356	    await db.playerSession.update({ where: { id: open.id }, data: { leftAt: new Date(), leftAtInferred: inferred } });
357	  }
