360	/**
361	 * Track player join/leave for game families with NO remote console (Valheim
362	 * today, via GAME_LOG_TRACKING in lib/game-control.ts) by tailing their own log
363	 * instead of RCON — `readGameLogs`, the exact same read-only path the Console
364	 * tab already uses. Runs every ~60s from the main loop, ALONGSIDE (not instead
365	 * of) `playerTrackingSweep` above — a server only ever matches one of the two,
366	 * since `logTrackingSpec` is only registered for families with `rcon: "none"`.
367	 *
368	 * THE REAL LIMITATION — read this before changing the inference below. Valheim's
369	 * dedicated-server log names a player on JOIN
370	 * (`Got character ZDOID from <name> : <id>`) but NOT on disconnect — a
371	 * disconnect only ever updates a running headcount (`... now N player(s)`). So
372	 * when the count drops we know FOR CERTAIN that one fewer player is connected,
373	 * but NOT which one. This sweep's handling of that gap:
374	 *
375	 *   - `onlineCount` always tracks the log's own headcount line exactly —
376	 *     ground truth, never guessed.
377	 *   - `onlineNames` (persisted on GameLogCursor) is a FIFO of names in join
378	 *     order. On a headcount decrement, the OLDEST believed-online name is
379	 *     popped and ITS PlayerSession is closed with `leftAtInferred: true` — a
380	 *     guess, not an observation, and wrong whenever the player who actually
381	 *     left isn't the longest-connected one of the group. `leftAtInferred` is
382	 *     surfaced in the UI (GamePlayerHistory) so this is never presented as
383	 *     fact.
384	 *   - If the count hits exactly 0, every remaining open session for the
385	 *     server is closed — that IS certain (nobody is connected), so those are
386	 *     NOT marked inferred.
387	 *   - If a JOIN names someone the FIFO still believes is online (drift from an
388	 *     earlier wrong guess), that stale session is closed first (inferred)
389	 *     before the fresh one opens, so drift self-corrects instead of piling up.
390	 *   - A count INCREASE with no matching join line parsed in this batch is left
391	 *     alone rather than inventing a name — `onlineCount` still updates.
392	 *
393	 * Incremental tailing: `GameLogCursor.lastLine` is the last raw line this sweep
394	 * already processed; each run only walks lines after that mark in the new tail.
395	 * `readGameLogs` is capped at the last 500 lines (lib/game-control.ts), so a
396	 * server producing >500 log lines between two ~60s sweeps could skip events —
397	 * acceptable for Valheim's actual join/leave volume, but worth knowing if this
398	 * pattern is reused for a chattier log. If the previous marker line has rolled
399	 * completely out of the new tail, this run processes nothing (rather than risk
400	 * double-counting) and just re-marks the newest line. On a server's very first
401	 * sweep (no GameLogCursor row yet) nothing is back-filled as a join — there is
402	 * no way to know when an already-connected player actually joined — so the
403	 * cursor is seeded silently and tracking starts clean from the next line on.
404	 */
405	export async function logPlayerTrackingSweep(): Promise<void> {
406	  if (SANDBOX) return;
407	
408	  const servers = await db.server.findMany({
409	    where: { status: "RUNNING", gamePlanId: { not: null } },
410	    select: CONTROL_FIELDS,
411	  });
412	
413	  for (const server of servers) {
414	    try {
415	      const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
416	      if (!isGameFamily(fam)) continue;
417	      const spec = controlSpec(fam);
418	      const tracking = logTrackingSpec(fam);
419	      if (!spec || !tracking) continue; // only families with a registered log-tracking spec
420	
421	      const logRes = await withServerSsh(server as SftpServer, (conn) => readGameLogs(conn, spec, 500));
422	      if (!logRes.ok) continue;
423	      const lines = logRes.lines;
424	      if (lines.length === 0) continue;
425	
426	      const cursor = await db.gameLogCursor.findUnique({ where: { serverId: server.id } });
427	      const isFirstSweep = !cursor;
428	
429	      let startIdx = lines.length; // default: process nothing (marker missing/rolled out)
430	      if (isFirstSweep) {
431	        startIdx = lines.length; // seed only — no back-fill, see doc comment
432	      } else if (cursor!.lastLine == null) {
433	        startIdx = 0; // a cursor existed but had no marker yet (shouldn't normally happen)
434	      } else {
435	        const idx = lines.lastIndexOf(cursor!.lastLine);
436	        startIdx = idx >= 0 ? idx + 1 : lines.length;
437	      }
438	
439	      let onlineNames: string[] = Array.isArray(cursor?.onlineNames) ? [...(cursor!.onlineNames as unknown as string[])] : [];
440	      let onlineCount = cursor?.onlineCount ?? 0;
441	
442	      for (let i = startIdx; i < lines.length; i++) {
443	        const line = lines[i];
444	
445	        const joinM = tracking.joinRe.exec(line);
446	        if (joinM) {
447	          const name = joinM[1].trim();
448	          if (name) {
449	            const dupIdx = onlineNames.findIndex((n) => n.toLowerCase() === name.toLowerCase());
450	            if (dupIdx >= 0) {
451	              // FIFO drift: we thought they were already online. Close the
452	              // stale (inferred) session before opening the real new one.
453	              onlineNames.splice(dupIdx, 1);
454	              await closeOpenLogSession(server.id, name, true);
455	            }
456	            onlineNames.push(name);
457	            await db.playerSession.create({ data: { serverId: server.id, playerName: name } });
458	          }
459	          continue;
460	        }
461	
462	        const countM = tracking.countRe.exec(line);
463	        if (countM) {
464	          const newCount = Number(countM[1]);
465	          if (Number.isFinite(newCount) && newCount !== onlineCount) {
466	            if (newCount === 0) {
467	              await db.playerSession.updateMany({
468	                where: { serverId: server.id, leftAt: null },
469	                data: { leftAt: new Date(), leftAtInferred: false },
470	              });
471	              onlineNames = [];
472	            } else if (newCount < onlineCount) {
473	              const drop = onlineCount - newCount;
474	              for (let d = 0; d < drop && onlineNames.length > 0; d++) {
475	                const leaver = onlineNames.shift()!;
476	                await closeOpenLogSession(server.id, leaver, true);
477	              }
478	            }
479	            onlineCount = newCount;
480	          }
481	        }
482	      }
483	
484	      const lastLine = lines[lines.length - 1];
485	      await db.gameLogCursor.upsert({
486	        where: { serverId: server.id },
487	        create: { serverId: server.id, lastLine, onlineNames, onlineCount },
488	        update: { lastLine, onlineNames, onlineCount },
489	      });
490	    } catch (e) {
491	      console.error(`[log-player-tracking] sweep failed for server ${server.id}`, e);
492	    }
493	  }
494	}
