56	if (!Number.isInteger(PORT) || PORT < 1 || PORT > 65535) {
57	  console.error(`[node-agent] NXEON_AGENT_PORT=${process.env.NXEON_AGENT_PORT} is not a valid port — refusing to start.`);
58	  process.exit(1);
59	}
