61	// ---- Validation — mirrors lib/nat-rules.ts's own rules; keep in sync ------
62	const IPV4_RE = /^(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;
63	const CHAIN_RE = /^[A-Z0-9_]{1,40}$/;
64	const STORAGE_RE = /^[a-zA-Z0-9_-]{1,60}$/;
65	// Matches exactly the filenames worker/index.ts's provision() ever asks for:
66	// nxeon-<vmid>.yaml. Nothing else is ever written or deleted by this agent.
67	const FILENAME_RE = /^nxeon-\d+\.yaml$/;
68	// Root of this node's own local disaster-recovery backups (see
69	// scripts/backup-vms.sh / backup-pve-config.sh, which write here directly —
70	// this agent never writes into it, only reads). Matches those scripts'
71	// own NXEON_PLATFORM_BACKUP_DIR/NXEON_BACKUP_STATUS_DIR defaults
72	// (/tank/backup/platform, /tank/backup/status), one level up.
73	const BACKUP_ROOT = process.env.NXEON_AGENT_BACKUP_ROOT || "/tank/backup";
74	// Allowlist of relative paths this agent will ever list or stream — exactly
75	// the filenames backup-pve-config.sh / backup-vms.sh produce. Read-only:
76	// there is no write/delete counterpart, unlike the snippet endpoints above —
77	// the primary only ever pulls from here, never pushes.
78	const BACKUP_REL_RE =
79	  /^(platform\/(host-config-\d{8}-\d{6}\.tar\.gz|vzdump-qemu-\d+-\d{4}_\d{2}_\d{2}-\d{2}_\d{2}_\d{2}\.(vma\.zst|log)|vm-names\.txt)|status\/(host-config|vm-backup)\.json)$/;
80	
81	/** True only for an actual string matching `re` — RegExp#test() coerces its
82	 *  argument, so `CHAIN_RE.test(123)` would otherwise pass (stringifies to
83	 *  "123", which matches [A-Z0-9_]) and hand a NUMBER to execFile's argv array
84	 *  a few lines later. Every JSON-body-derived field is checked with this,
85	 *  never a bare `.test()`, so a type-confused value is rejected up front
86	 *  instead of surfacing as a confusing execFile error downstream. */
87	function isStr(v, re) {
88	  return typeof v === "string" && re.test(v);
89	}
90	
91	function isValidPort(n) {
92	  return Number.isInteger(n) && n >= 1 && n <= 65535;
93	}
94	function isValidRule(r) {
95	  return (
96	    !!r &&
97	    (r.proto === "tcp" || r.proto === "udp") &&
98	    isValidPort(r.dport) &&
99	    typeof r.destIp === "string" &&
100	    IPV4_RE.test(r.destIp) &&
101	    isValidPort(r.destPort)
102	  );
103	}
104	/** Argv fragment shared by -A/-D — mirrors lib/nat-rules.ts's ruleSpec(). */
105	function ruleSpec(r) {
106	  return ["-p", r.proto, "--dport", String(r.dport), "-j", "DNAT", "--to-destination", `${r.destIp}:${r.destPort}`];
107	}
108	
109	// ---- constant-time bearer check --------------------------------------------
110	function checkAuth(req) {
111	  const header = req.headers["authorization"] || "";
112	  const m = /^Bearer (.+)$/.exec(header);
113	  if (!m) return false;
114	  const presented = Buffer.from(m[1]);
115	  const expected = Buffer.from(TOKEN);
116	  // timingSafeEqual throws on a length mismatch rather than returning false —
117	  // guard it explicitly so a short/garbled header can't produce a stack trace.
118	  if (presented.length !== expected.length) return false;
119	  return crypto.timingSafeEqual(presented, expected);
120	}
