122	// ---- iptables exec — argv arrays only, NEVER a shell string ----------------
123	function iptables(args) {
124	  return new Promise((resolve, reject) => {
125	    execFile("iptables", args, { timeout: CMD_TIMEOUT_MS }, (err, stdout, stderr) => {
126	      if (err) return reject(new Error(String(stderr || err.message).trim().slice(0, 400)));
127	      resolve(stdout);
128	    });
129	  });
