132	async function ensureChain(chain) {
133	  try {
134	    await iptables(["-t", "nat", "-N", chain]);
135	  } catch {
136	    /* chain already exists */
137	  }
138	  try {
139	    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", chain]);
140	  } catch {
141	    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", chain]);
142	  }
