145	function pvesmPath(storageRef) {
146	  return new Promise((resolve, reject) => {
147	    execFile("pvesm", ["path", storageRef], { timeout: 10_000 }, (err, stdout) => {
148	      if (err) return reject(new Error(`pvesm path ${storageRef}: ${err.message}`));
149	      resolve(stdout.trim());
150	    });
151	  });
152	}
