154	// ---- request body helpers ---------------------------------------------------
155	function readBody(req) {
156	  return new Promise((resolve, reject) => {
157	    let size = 0;
158	    const chunks = [];
159	    req.on("data", (c) => {
160	      size += c.length;
161	      if (size > MAX_BODY_BYTES) {
162	        reject(new Error("request body too large"));
163	        req.destroy();
164	        return;
165	      }
166	      chunks.push(c);
167	    });
168	    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
169	    req.on("error", reject);
170	  });
171	}
