240	async function handleWriteSnippet(_req, res, rawBody) {
241	  const parsed = parseJson(rawBody);
242	  if (!parsed || !STORAGE_RE.test(parsed.storage || "")) return sendJson(res, 400, { error: "invalid storage id" });
243	  if (!FILENAME_RE.test(parsed.filename || "")) return sendJson(res, 400, { error: "invalid filename" });
244	  if (typeof parsed.content !== "string" || parsed.content.length > MAX_BODY_BYTES) {
245	    return sendJson(res, 400, { error: "invalid content" });
246	  }
247	  const target = await resolveSnippetPath(parsed.storage, parsed.filename);
248	  fs.mkdirSync(path.dirname(target), { recursive: true });
249	  fs.writeFileSync(target, parsed.content, { mode: 0o600 });
250	  sendJson(res, 200, { ok: true });
251	}
252	
253	async function handleDeleteSnippet(_req, res, rawBody) {
254	  const parsed = parseJson(rawBody);
255	  if (!parsed || !STORAGE_RE.test(parsed.storage || "")) return sendJson(res, 400, { error: "invalid storage id" });
256	  if (!FILENAME_RE.test(parsed.filename || "")) return sendJson(res, 400, { error: "invalid filename" });
257	  const target = await resolveSnippetPath(parsed.storage, parsed.filename);
258	  fs.rmSync(target, { force: true });
259	  sendJson(res, 200, { ok: true });
260	}
261	
262	async function handleDnatCheck(_req, res, address) {
263	  if (!IPV4_RE.test(address || "")) return sendJson(res, 400, { error: "invalid address" });
264	  const output = await iptables(["-t", "nat", "-S", "PREROUTING"]);
265	  const hasLiveDnatRule = output.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
266	  sendJson(res, 200, { hasLiveDnatRule });
267	}
268	
269	/** Recursively-flat listing of the two backup subdirs this agent exposes —
270	 *  each entry's `path` is exactly what handleBackupFile expects back. Missing
271	 *  subdirs (e.g. a node with no vzdump guests yet) are not an error — an
272	 *  empty/partial manifest is itself the honest signal the primary's collector
273	 *  needs to raise, not something this endpoint should paper over. */
274	async function handleBackupManifest(_req, res) {
275	  const entries = [];
276	  for (const sub of ["platform", "status"]) {
277	    const dir = path.join(BACKUP_ROOT, sub);
278	    let names;
279	    try {
280	      names = fs.readdirSync(dir);
281	    } catch {
282	      continue; // subdir doesn't exist on this node yet — not an error
283	    }
284	    for (const name of names) {
285	      const rel = `${sub}/${name}`;
286	      if (!BACKUP_REL_RE.test(rel)) continue; // silently skip anything not on the allowlist
287	      let st;
288	      try {
289	        st = fs.statSync(path.join(dir, name));
290	      } catch {
291	        continue;
292	      }
293	      if (!st.isFile()) continue;
294	      entries.push({ path: rel, size: st.size, mtimeMs: st.mtimeMs });
295	    }
296	  }
297	  sendJson(res, 200, { entries });
298	}
299	
300	/** Stream one backup file's raw bytes. `relPath` must match BACKUP_REL_RE
301	 *  (rules out traversal by construction — no `..`, no absolute path, no
302	 *  extension this platform doesn't itself produce) AND the resolved real
303	 *  path must land inside BACKUP_ROOT — same defense-in-depth shape as
304	 *  resolveSnippetPath() above, kept even though the regex alone should
305	 *  already be sufficient. */
306	async function handleBackupFile(_req, res, relPath) {
307	  if (!isStr(relPath, BACKUP_REL_RE)) return sendJson(res, 400, { error: "invalid path" });
308	  const full = path.join(BACKUP_ROOT, relPath);
309	  let real;
310	  try {
311	    real = fs.realpathSync(full);
312	  } catch {
313	    return sendJson(res, 404, { error: "not found" });
314	  }
315	  const rootReal = fs.realpathSync(BACKUP_ROOT);
316	  if (real !== rootReal && !real.startsWith(rootReal + path.sep)) {
317	    return sendJson(res, 400, { error: "path escapes backup root" });
318	  }
319	  let st;
320	  try {
321	    st = fs.statSync(real);
322	  } catch {
323	    return sendJson(res, 404, { error: "not found" });
324	  }
325	  if (!st.isFile()) return sendJson(res, 404, { error: "not found" });
326	  res.writeHead(200, {
327	    "Content-Type": "application/octet-stream",
328	    "Content-Length": st.size,
329	    "Content-Disposition": `attachment; filename="${path.basename(real)}"`,
330	  });
331	  fs.createReadStream(real).pipe(res);
332	}
333	
334	// ---- router ------------------------------------------------------------------
335	
336	async function route(req, res) {
337	  const url = new URL(req.url, `https://${req.headers.host || "localhost"}`);
338	  const { pathname, searchParams } = url;
339	
340	  if (req.method === "GET" && pathname === "/v1/health") return handleHealth(req, res);
341	
342	  if (req.method === "POST" && pathname === "/v1/nat/ensure-chain") return handleEnsureChain(req, res, await readBody(req));
343	
344	  const chainMatch = /^\/v1\/nat\/chain\/([^/]+)$/.exec(pathname);
345	  if (req.method === "GET" && chainMatch) return handleListChain(req, res, decodeURIComponent(chainMatch[1]));
346	
347	  if (req.method === "POST" && pathname === "/v1/nat/rule") return handleAddRule(req, res, await readBody(req));
348	  if (req.method === "DELETE" && pathname === "/v1/nat/rule") return handleDeleteRule(req, res, await readBody(req));
349	
350	  if (req.method === "POST" && pathname === "/v1/snippet") return handleWriteSnippet(req, res, await readBody(req));
351	  if (req.method === "DELETE" && pathname === "/v1/snippet") return handleDeleteSnippet(req, res, await readBody(req));
352	
353	  if (req.method === "GET" && pathname === "/v1/iptables/dnat-check") return handleDnatCheck(req, res, searchParams.get("address"));
354	
355	  if (req.method === "GET" && pathname === "/v1/backup/manifest") return handleBackupManifest(req, res);
356	  if (req.method === "GET" && pathname === "/v1/backup/file") return handleBackupFile(req, res, searchParams.get("path"));
357	
358	  sendJson(res, 404, { error: "not found" });
359	}
360	
361	const server = https.createServer({ key: fs.readFileSync(TLS_KEY), cert: fs.readFileSync(TLS_CERT) }, (req, res) => {
362	  if (!checkAuth(req)) {
363	    sendJson(res, 401, { error: "unauthorized" });
364	    return;
365	  }
366	  route(req, res).catch((e) => {
367	    console.error("[node-agent] request error:", e && e.message ? e.message : e);
368	    try {
369	      sendJson(res, 500, { error: String((e && e.message) || e).slice(0, 300) });
370	    } catch {
371	      /* response already sent/closed */
372	    }
373	  });
374	});
375	
376	server.listen(PORT, () => {
377	  console.log(`[node-agent] listening on :${PORT}`);
378	});
