1	/**
2	 * Server-side SFTP proxy for the in-portal file manager.
3	 *
4	 * This is a plain (non-"use server") module so it can be imported by both the
5	 * server actions (lib/actions-files.ts) and the upload/download route handler.
6	 * It never runs in the browser — the customer's root credentials stay on the
7	 * server; the browser only ever talks to our own actions/route.
8	 *
9	 * Connection target is derived EXACTLY like the server detail page:
10	 *   - dedicated-IP servers connect to their own IP on port 22
11	 *   - NAT servers use PUBLIC_IP + the forwarded SSH port
12	 * Username is always "root"; password is `server.rootPassword`.
13	 *
14	 * SANDBOX: on staging (NXEON_SANDBOX=1) no real SSH connection is ever opened —
15	 * every op is backed by a small in-memory simulated filesystem so the whole
16	 * file-manager UX works end to end without a live VM.
17	 */
18	import SftpClient from "ssh2-sftp-client";
19	import { SANDBOX } from "./sandbox";
20	import { decryptSecret } from "./crypto-box";
21	
22	/**
23	 * Resolve a server's plaintext root password, preferring the encrypted-at-rest
24	 * value and falling back to the legacy plaintext column for rows that predate
25	 * encryption. Every READ of a root password must go through this helper so both
26	 * shapes keep working transparently.
27	 */
28	export function serverRootPassword(
29	  server: { rootPassword: string | null; rootPasswordEnc?: string | null }
30	): string | null {
31	  return decryptSecret(server.rootPasswordEnc) ?? server.rootPassword;
32	}
33	
34	/** The minimal shape of a Server we need to open a connection. */
35	export type SftpServer = {
36	  id: string;
37	  rootPassword: string | null;
38	  rootPasswordEnc?: string | null;
39	  sshPort: number | null;
40	  dedicatedIp?: { address: string } | null;
41	  /** The server's own node — vmids/ports are per-node, so a NAT (non-dedicated-IP)
42	   *  server's real SSH host is THIS node's public IP, not necessarily the
43	   *  platform's env-configured primary. Optional so existing callers that don't
44	   *  select it keep today's exact fallback behavior (see connectionTarget). */
45	  node?: { publicIp: string } | null;
46	};
47	
48	export type SftpEntry = {
49	  name: string;
50	  /** "d" directory, "-" file, "l" symlink, etc. (ssh2-sftp-client `type`). */
51	  type: string;
52	  isDirectory: boolean;
53	  size: number;
54	  /** Unix mtime in ms. */
55	  modifiedMs: number;
56	  /** Numeric permission bits (e.g. 0o644), or null if unknown. */
57	  mode: number | null;
58	};
59	
60	export type SftpStat = {
61	  isDirectory: boolean;
62	  size: number;
63	  modifiedMs: number;
64	  mode: number | null;
65	};
66	
67	const CONNECT_TIMEOUT_MS = 10_000;
68	
69	/** Max length for any absolute path we accept from the client. */
70	export const MAX_PATH_LEN = 4096;
71	/** Max length for a single path segment (file/folder name). */
72	export const MAX_NAME_LEN = 255;
73	
74	/**
75	 * Normalize + validate an absolute POSIX path coming from the browser. Rejects
76	 * relative paths, `..` traversal, NUL bytes, and over-long paths. Returns a
77	 * cleaned absolute path (collapsed slashes, resolved `.`), always starting with
78	 * "/". Throws on anything suspicious — callers surface the message.
79	 */
80	export function normalizePath(input: string): string {
81	  if (typeof input !== "string") throw new Error("Invalid path.");
82	  if (input.length > MAX_PATH_LEN) throw new Error("Path is too long.");
83	  if (input.includes("\0")) throw new Error("Invalid path.");
84	  if (!input.startsWith("/")) throw new Error("Path must be absolute.");
85	
86	  const out: string[] = [];
87	  for (const part of input.split("/")) {
88	    if (part === "" || part === ".") continue;
89	    if (part === "..") throw new Error("Path traversal is not allowed.");
90	    if (part.length > MAX_NAME_LEN) throw new Error("A path segment is too long.");
91	    out.push(part);
92	  }
93	  return "/" + out.join("/");
94	}
95	
96	/**
97	 * Validate a single new file/folder name — no slashes, no traversal, no NUL,
98	 * not "." or "..". Returns the name unchanged if valid.
99	 */
100	export function validateName(name: string): string {
101	  if (typeof name !== "string" || name.length === 0) throw new Error("A name is required.");
102	  if (name.length > MAX_NAME_LEN) throw new Error("Name is too long.");
103	  if (name.includes("/") || name.includes("\0")) throw new Error("Name contains invalid characters.");
104	  if (name === "." || name === "..") throw new Error("That name is not allowed.");
105	  return name;
106	}
107	
108	/** Join a validated absolute dir with a validated name, re-normalizing. */
109	export function joinPath(dir: string, name: string): string {
110	  return normalizePath(`${dir}/${name}`);
111	}
112	
113	/**
114	 * Fixed directory every browser→server upload lands in. Uploads are ALWAYS
115	 * written here under a sanitized basename — never at a client-chosen path — so
116	 * a hostile filename can only ever create a file inside this one dir. Lives in
117	 * this plain module (not the "use server" action file) so it can be imported
118	 * and unit-tested without pulling in the server-action graph.
119	 */
120	export const UPLOAD_DIR = "/root/nxeon-uploads";
121	
122	/**
123	 * Reduce an arbitrary, client-supplied filename to a SAFE basename that can only
124	 * land inside {@link UPLOAD_DIR}. Strips every directory component (POSIX `/`
125	 * and Windows `\`) so `../../etc/passwd` or `C:\evil\x` collapse to their final
126	 * segment, then runs the survivor through the same `validateName` the file
127	 * manager uses (rejects `/`, NUL, `.`, `..`, over-long names). Pure so the guard
128	 * can be unit-tested in isolation from any SFTP connection.
129	 */
130	export function sanitizeUploadName(raw: string): string {
131	  if (typeof raw !== "string") throw new Error("A name is required.");
132	  const base = raw.split(/[/\\]/).pop() ?? "";
133	  const trimmed = base.trim();
134	  if (!trimmed) throw new Error("A name is required.");
135	  return validateName(trimmed);
136	}
137	
138	/**
139	 * Resolve the {host, port} for a server, mirroring the server detail page:
140	 * dedicated IP -> :22, otherwise the server's OWN node's public IP : sshPort
141	 * (falling back to the platform's env-configured primary only when the
142	 * server genuinely has no node relation — e.g. not yet selected by an older
143	 * caller, or a row that predates multi-node). Getting this wrong for a
144	 * server on a non-primary node means dialing the WRONG physical host
145	 * entirely, not just a wrong port — verified live 2026-09-05 as the root
146	 * cause of an entire class of "control panel dead for node-2" bugs.
147	 */
148	export function connectionTarget(server: SftpServer): { host: string; port: number } | null {
149	  const dedicated = !!server.dedicatedIp;
150	  const host = dedicated ? server.dedicatedIp!.address : (server.node?.publicIp ?? process.env.PUBLIC_IP ?? "");
151	  const port = dedicated ? 22 : server.sshPort;
152	  if (!host || !port) return null;
153	  return { host, port };
154	}
155	
156	/**
157	 * Open an SFTP connection, run `fn(client)`, and ALWAYS close it (finally).
158	 * In SANDBOX mode this is bypassed entirely — callers below short-circuit to
159	 * the in-memory filesystem before ever reaching here.
160	 */
161	export async function withSftp<T>(
162	  server: SftpServer,
163	  fn: (client: SftpClient) => Promise<T>
164	): Promise<T> {
165	  if (SANDBOX) {
166	    throw new Error("withSftp must not be called in sandbox mode");
167	  }
168	  const target = connectionTarget(server);
169	  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
170	  const password = serverRootPassword(server);
171	  if (!password) throw new Error("Server has no root password set.");
172	
173	  const client = new SftpClient();
174	  try {
175	    await client.connect({
176	      host: target.host,
177	      port: target.port,
178	      username: "root",
179	      password,
180	      readyTimeout: CONNECT_TIMEOUT_MS,
181	    });
182	    return await fn(client);
183	  } finally {
184	    try {
185	      await client.end();
186	    } catch {
187	      /* best-effort close */
188	    }
189	  }
190	}
191	
192	// ----------------------------------------------------------------------------
193	// Sandbox in-memory filesystem
194	// ----------------------------------------------------------------------------
195	
196	type SimNode =
197	  | { type: "dir"; mtime: number; mode: number; children: Record<string, SimNode> }
198	  | { type: "file"; mtime: number; mode: number; content: string };
199	type SimDir = Extract<SimNode, { type: "dir" }>;
200	
201	/** One simulated filesystem per server id, lazily seeded. */
202	const globalForSim = globalThis as unknown as { __nxeonSftpSim?: Map<string, SimNode> };
203	const simStore: Map<string, SimNode> = globalForSim.__nxeonSftpSim ?? new Map();
204	globalForSim.__nxeonSftpSim = simStore;
205	
206	function seedSim(): SimNode {
207	  const now = Date.now();
208	  const file = (content: string, mode = 0o644): SimNode => ({
209	    type: "file",
210	    mtime: now,
211	    mode,
212	    content,
213	  });
214	  const dir = (children: Record<string, SimNode>, mode = 0o755): SimNode => ({
215	    type: "dir",
216	    mtime: now,
217	    mode,
218	    children,
219	  });
220	  return dir({
221	    root: dir({
222	      "readme.txt": file(
223	        "Welcome to your VPS (sandbox).\n\nThis is a simulated filesystem shown on the staging\nenvironment — no real SSH connection is made.\n"
224	      ),
225	      ".bashrc": file("# ~/.bashrc\nexport PATH=$PATH:/usr/local/bin\n"),
226	      projects: dir({
227	        "app.js": file("console.log('hello from your server');\n"),
228	        "notes.md": file("# Notes\n\n- Edit me from the file manager.\n"),
229	      }),
230	    }),
231	    etc: dir({
232	      "hostname": file("nxeon-vps\n"),
233	      "os-release": file('PRETTY_NAME="Ubuntu 24.04 LTS"\n', 0o644),
234	    }),
235	    var: dir({
236	      log: dir({
237	        "syslog": file("Jan  1 00:00:00 nxeon-vps systemd[1]: Started sandbox.\n"),
238	      }),
239	      www: dir({
240	        html: dir({
241	          "index.html": file("<!doctype html><h1>It works</h1>\n"),
242	        }),
243	      }),
244	    }),
245	    tmp: dir({}),
246	  });
247	}
248	
249	function simRoot(serverId: string): SimNode {
250	  let node = simStore.get(serverId);
251	  if (!node) {
252	    node = seedSim();
253	    simStore.set(serverId, node);
254	  }
255	  return node;
256	}
257	
258	/** Convert an rwx rights triad ("rwx","r-x","r--") into an octal mode integer. */
259	function rightsToMode(rights: { user: string; group: string; other: string }): number | null {
260	  if (!rights) return null;
261	  const bits = (s: string): number =>
262	    (s.includes("r") ? 4 : 0) + (s.includes("w") ? 2 : 0) + (s.includes("x") ? 1 : 0);
263	  return (bits(rights.user) << 6) | (bits(rights.group) << 3) | bits(rights.other);
264	}
265	
266	function splitPath(p: string): string[] {
267	  return p.split("/").filter((s) => s.length > 0);
268	}
269	
270	function simResolve(serverId: string, p: string): SimNode | null {
271	  let node = simRoot(serverId);
272	  for (const part of splitPath(p)) {
273	    if (node.type !== "dir") return null;
274	    const next = node.children[part];
275	    if (!next) return null;
276	    node = next;
277	  }
278	  return node;
279	}
280	
281	function simParent(serverId: string, p: string): { parent: SimDir; name: string } | null {
282	  const parts = splitPath(p);
283	  if (parts.length === 0) return null;
284	  const name = parts[parts.length - 1];
285	  const parentPath = "/" + parts.slice(0, -1).join("/");
286	  const parent = simResolve(serverId, parentPath);
287	  if (!parent || parent.type !== "dir") return null;
288	  return { parent, name };
289	}
290	
291	// ----------------------------------------------------------------------------
292	// Typed operations (sandbox-aware)
293	// ----------------------------------------------------------------------------
294	
295	export async function listDir(server: SftpServer, path: string): Promise<SftpEntry[]> {
296	  if (SANDBOX) {
297	    const node = simResolve(server.id, path);
298	    if (!node) throw new Error("No such directory.");
299	    if (node.type !== "dir") throw new Error("Not a directory.");
300	    return Object.entries(node.children)
301	      .map(([name, child]) => ({
302	        name,
303	        type: child.type === "dir" ? "d" : "-",
304	        isDirectory: child.type === "dir",
305	        size: child.type === "file" ? Buffer.byteLength(child.content) : 0,
306	        modifiedMs: child.mtime,
307	        mode: child.mode,
308	      }))
309	      .sort((a, b) =>
310	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
311	      );
312	  }
313	
314	  return withSftp(server, async (client) => {
315	    const list = await client.list(path);
316	    return list
317	      .map((e) => ({
318	        name: e.name,
319	        type: e.type,
320	        isDirectory: e.type === "d",
321	        size: e.size,
322	        modifiedMs: e.modifyTime,
323	        // ssh2-sftp-client's list() returns rwx `rights` strings, not a numeric
324	        // mode — derive the octal permission bits from them.
325	        mode: rightsToMode(e.rights),
326	      }))
327	      .sort((a, b) =>
328	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
329	      );
330	  });
331	}
332	
333	export async function statPath(server: SftpServer, path: string): Promise<SftpStat> {
334	  if (SANDBOX) {
335	    const node = simResolve(server.id, path);
336	    if (!node) throw new Error("No such file or directory.");
337	    return {
338	      isDirectory: node.type === "dir",
339	      size: node.type === "file" ? Buffer.byteLength(node.content) : 0,
340	      modifiedMs: node.mtime,
341	      mode: node.mode,
342	    };
343	  }
344	
345	  return withSftp(server, async (client) => {
346	    const s = await client.stat(path);
347	    return {
348	      isDirectory: s.isDirectory,
349	      size: s.size,
350	      modifiedMs: s.modifyTime,
351	      mode: typeof s.mode === "number" ? s.mode & 0o777 : null,
352	    };
353	  });
354	}
355	
356	/**
357	 * Read a text file, capped at `maxBytes`. Throws if the target is larger than
358	 * the cap so we never buffer an unbounded file into memory / the editor.
359	 */
360	export async function readFileText(
361	  server: SftpServer,
362	  path: string,
363	  maxBytes: number
364	): Promise<string> {
365	  if (SANDBOX) {
366	    const node = simResolve(server.id, path);
367	    if (!node) throw new Error("No such file.");
368	    if (node.type !== "file") throw new Error("Not a file.");
369	    if (Buffer.byteLength(node.content) > maxBytes) {
370	      throw new Error("File is too large to edit in the browser.");
371	    }
372	    return node.content;
373	  }
374	
375	  return withSftp(server, async (client) => {
376	    const s = await client.stat(path);
377	    if (s.isDirectory) throw new Error("Not a file.");
378	    if (s.size > maxBytes) throw new Error("File is too large to edit in the browser.");
379	    const buf = (await client.get(path)) as Buffer;
380	    return buf.toString("utf8");
381	  });
382	}
383	
384	export async function writeFileText(
385	  server: SftpServer,
386	  path: string,
387	  content: string
388	): Promise<void> {
389	  if (SANDBOX) {
390	    const loc = simParent(server.id, path);
391	    if (!loc) throw new Error("Invalid path.");
392	    const existing = loc.parent.children[loc.name];
393	    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
394	    loc.parent.children[loc.name] = {
395	      type: "file",
396	      mtime: Date.now(),
397	      mode: existing?.type === "file" ? existing.mode : 0o644,
398	      content,
399	    };
400	    return;
401	  }
402	
403	  await withSftp(server, async (client) => {
404	    await client.put(Buffer.from(content, "utf8"), path);
405	  });
406	}
407	
408	export async function mkdirPath(server: SftpServer, path: string): Promise<void> {
409	  if (SANDBOX) {
410	    const loc = simParent(server.id, path);
411	    if (!loc) throw new Error("Invalid path.");
412	    if (loc.parent.children[loc.name]) throw new Error("A file or folder with that name already exists.");
413	    loc.parent.children[loc.name] = { type: "dir", mtime: Date.now(), mode: 0o755, children: {} };
414	    return;
415	  }
416	
417	  await withSftp(server, async (client) => {
418	    await client.mkdir(path, false);
419	  });
