422	export async function renamePath(
423	  server: SftpServer,
424	  from: string,
425	  to: string
426	): Promise<void> {
427	  if (SANDBOX) {
428	    const src = simResolve(server.id, from);
429	    if (!src) throw new Error("No such file or directory.");
430	    const dst = simParent(server.id, to);
431	    if (!dst) throw new Error("Invalid destination.");
432	    if (dst.parent.children[dst.name]) {
433	      throw new Error("A file or folder with that name already exists.");
434	    }
435	    const srcLoc = simParent(server.id, from);
436	    if (!srcLoc) throw new Error("Cannot rename the root.");
437	    delete srcLoc.parent.children[srcLoc.name];
438	    dst.parent.children[dst.name] = { ...src, mtime: Date.now() };
439	    return;
440	  }
441	
442	  await withSftp(server, async (client) => {
443	    await client.rename(from, to);
444	  });
445	}
