484	/** Read an entire file into a Buffer (used by the download endpoint). */
485	export async function readFileBuffer(server: SftpServer, path: string): Promise<Buffer> {
486	  if (SANDBOX) {
487	    const node = simResolve(server.id, path);
488	    if (!node) throw new Error("No such file.");
489	    if (node.type !== "file") throw new Error("Not a file.");
490	    return Buffer.from(node.content, "utf8");
491	  }
492	
493	  return withSftp(server, async (client) => {
494	    const s = await client.stat(path);
495	    if (s.isDirectory) throw new Error("Not a file.");
496	    return (await client.get(path)) as Buffer;
497	  });
498	}
