254	/** The minimal Server shape the real path needs to open an SSH connection. */
255	export type SshServer = {
256	  id: string;
257	  rootPassword: string | null;
258	  rootPasswordEnc?: string | null;
259	  sshPort: number | null;
260	  dedicatedIp?: { address: string } | null;
261	  node?: { publicIp: string } | null;
262	  gameVariant?: string | null;
