265	/**
266	 * Connect to the game-server VM (host/port derived exactly like the file manager,
267	 * user "root", password `rootPassword`), run `fn`, and always close the session.
268	 */
269	function withSsh<T>(server: SshServer, fn: (conn: Client, sftp: SFTPWrapper) => Promise<T>): Promise<T> {
270	  return new Promise((resolve, reject) => {
271	    const target = connectionTarget(server as any);
272	    if (!target) {
273	      reject(new Error("server is not reachable yet — connection details are pending"));
274	      return;
275	    }
276	    const password = serverRootPassword(server);
277	    if (!password) {
278	      reject(new Error("server has no root password set"));
279	      return;
280	    }
281	
282	    const conn = new Client();
283	    let settled = false;
284	    const finish = (err: Error | null, val?: T) => {
285	      if (settled) return;
286	      settled = true;
287	      try {
288	        conn.end();
289	      } catch {
290	        /* best-effort */
291	      }
292	      if (err) reject(err);
293	      else resolve(val as T);
294	    };
295	
296	    conn.on("ready", () => {
297	      conn.sftp((err, sftp) => {
298	        if (err) return finish(err);
299	        fn(conn, sftp).then((v) => finish(null, v)).catch((e) => finish(e instanceof Error ? e : new Error(String(e))));
300	      });
301	    });
302	    conn.on("error", (e) => finish(e instanceof Error ? e : new Error(String(e))));
303	    conn.connect({
304	      host: target.host,
305	      port: target.port,
306	      username: "root",
307	      password,
308	      readyTimeout: CONNECT_TIMEOUT_MS,
309	    });
310	  });
311	}
312	
313	/** Read a remote text file, or null if it does not exist. */
314	function sftpRead(sftp: SFTPWrapper, path: string): Promise<string | null> {
315	  return new Promise((resolve, reject) => {
316	    sftp.readFile(path, (err, data) => {
317	      if (err) {
318	        // ENOENT / no such file → null; anything else is a real error.
319	        const code = (err as NodeJS.ErrnoException).code;
320	        if (code === "ENOENT" || code === "No such file" || /no such file/i.test(err.message)) {
321	          return resolve(null);
322	        }
323	        return reject(err);
324	      }
325	      resolve(data.toString("utf8"));
326	    });
327	  });
328	}
329	
330	/** Write a remote text file (overwrites). */
331	function sftpWrite(sftp: SFTPWrapper, path: string, content: string): Promise<void> {
332	  return new Promise((resolve, reject) => {
333	    sftp.writeFile(path, Buffer.from(content, "utf8"), (err) => (err ? reject(err) : resolve()));
334	  });
335	}
336	
337	/** Write a remote binary file (overwrites) — same as sftpWrite but skips utf8 re-encoding. */
338	function sftpWriteBinary(sftp: SFTPWrapper, path: string, content: Buffer): Promise<void> {
339	  return new Promise((resolve, reject) => {
340	    sftp.writeFile(path, content, (err) => (err ? reject(err) : resolve()));
341	  });
342	}
343	
344	/** Run a remote shell command; resolves with stdout/stderr/exit-code (never rejects on non-zero). */
345	function execRemote(conn: Client, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
346	  return new Promise((resolve, reject) => {
347	    conn.exec(cmd, (err, stream: ClientChannel) => {
348	      if (err) return reject(err);
349	      let stdout = "";
350	      let stderr = "";
351	      const timer = setTimeout(() => {
352	        try {
353	          stream.close();
354	        } catch {
355	          /* ignore */
356	        }
357	      }, EXEC_TIMEOUT_MS);
358	      stream
359	        .on("close", (code: number) => {
360	          clearTimeout(timer);
361	          resolve({ code: code ?? 0, stdout, stderr });
362	        })
363	        .on("data", (d: Buffer) => (stdout += d.toString("utf8")))
364	        .stderr.on("data", (d: Buffer) => (stderr += d.toString("utf8")));
365	    });
366	  });
367	}
368	
369	/**
370	 * Locate the first existing path: try explicit candidates via `test -f`, then a
371	 * bounded `find` over `findRoots` for `findName`. Returns the path or null.
372	 * Non-destructive — only reads.
373	 */
374	async function remoteLocate(
375	  conn: Client,
376	  candidates: string[],
377	  findRoots: string[],
378	  findName: string
379	): Promise<string | null> {
380	  const testExpr = candidates.map((p) => `if [ -f '${shq(p)}' ]; then echo '${shq(p)}'; exit 0; fi;`).join(" ");
381	  const findExpr = findRoots.length
382	    ? `for r in ${findRoots.map((r) => `'${shq(r)}'`).join(" ")}; do [ -d "$r" ] && find "$r" -maxdepth 6 -type f -name '${shq(findName)}' 2>/dev/null | head -1; done | head -1`
383	    : "true";
384	  const { stdout } = await execRemote(conn, `${testExpr} ${findExpr}`);
385	  const hit = stdout.split(/\r?\n/).map((s) => s.trim()).find((s) => s.length > 0);
386	  return hit ?? null;
387	}
388	
389	/** Escape a value for single-quoted shell use. */
390	function shq(s: string): string {
391	  return s.replace(/'/g, "'\\''");
392	}
393	
394	/**
395	 * The systemd unit that supervises this family's game container, or null if the
396	 * guest has none.
397	 *
398	 * Every game family's setup script is rewritten at PROVISION time by
399	 * worker/index.ts's `wrapDockerGameService()` into `docker create` plus a
400	 * `<hint>.service` unit (`ExecStart=docker start -a <container>`,
401	 * `Restart=always`, `RestartSec=5`) — and that wrapper deliberately STRIPS
402	 * docker's own `--restart` policy, in its own words because "leaving both in
403	 * place makes the two supervisors fight over a crash-looping process". So on
404	 * every game server this platform provisions, systemd — not docker — owns the
405	 * container's lifecycle, and any apply path that stops or recreates a container
406	 * MUST go through it.
407	 *
408	 * Returns null when no unit resolves (a server provisioned before that wrapper
409	 * shipped, or a setup script that didn't match its `docker run -d --name X`
410	 * shape). There, docker's own restart policy is the only supervisor there is
411	 * and has to be preserved rather than replaced.
412	 *
413	 * The hints come from `lib/game-control.ts`'s per-family `controlSpec` — the
414	 * same list `worker/game-control.ts`'s power buttons resolve against, and the
415	 * same list `wrapDockerGameService` names the unit from ([0]) — so this can
416	 * never drift from the unit that actually got installed.
417	 */
418	async function resolveGameUnit(conn: Client, family: string): Promise<string | null> {
419	  const hints = controlSpec(family)?.serviceHints ?? [];
420	  if (!hints.length) return null;
421	  const probe = hints
422	    .map((h) => `systemctl cat '${shq(h)}.service' >/dev/null 2>&1 && { echo '${shq(h)}.service'; exit 0; };`)
423	    .join(" ");
424	  const { stdout } = await execRemote(conn, probe);
425	  const hit = stdout
426	    .split(/\r?\n/)
427	    .map((s) => s.trim())
428	    .find((s) => s.endsWith(".service"));
429	  return hit ?? null;
430	}
