432	/** Dispatch to the correct family renderer. Exported for direct, real-server
433	 *  verification of a family's real-apply path (see REAL_APPLY_FAMILIES's own
434	 *  comment for what "confirmed" means) — not called externally otherwise. */
435	export async function applyRealConfig(server: SshServer, family: string, values: Values): Promise<ApplyOutcome> {
436	  return withSsh(server, async (conn, sftp) => {
437	    switch (family) {
438	      case "minecraft":
439	        return applyMinecraft(conn, sftp, values);
440	      case "rust":
441	        return applyRust(conn, sftp, values);
442	      case "valheim":
443	        return applyValheim(conn, sftp, values, server.gameVariant ?? "vanilla");
444	      case "cs2":
445	        return applyCs2(conn, sftp, values);
446	      case "palworld":
447	        return applyPalworld(conn, sftp, values);
448	      case "bedrock":
449	        return applyBedrock(conn, sftp, values);
450	      default:
451	        return { ok: false, applied: [], notes: [`No real apply implemented for "${family}".`] };
452	    }
453	  });
454	}
