145	/** The identity of a rule for set operations — everything that makes it distinct. */
146	export function ruleKey(r: NatRule): string {
147	  return `${r.proto}/${r.dport}->${r.destIp}:${r.destPort}`;
148	}
149	
150	/** Human-readable, and close enough to the real command to paste after `iptables -t nat -A NXEON_FWD`. */
151	export function ruleText(r: NatRule): string {
152	  return `-p ${r.proto} --dport ${r.dport} -j DNAT --to-destination ${r.destIp}:${r.destPort}`;
153	}
154	
155	/** The argv fragment shared by -A, -D and -C. */
156	export function ruleSpec(r: NatRule): string[] {
157	  return [
158	    "-p", r.proto,
159	    "--dport", String(r.dport),
160	    "-j", "DNAT",
161	    "--to-destination", `${r.destIp}:${r.destPort}`,
162	  ];
163	}
