265	/**
266	 * Everything `reconcileNatChain` needs from the host, as an interface rather than
267	 * a bare `execFile`.
268	 *
269	 * WHY: this function edits the live NAT table of a production box carrying paying
270	 * customers. Its decision ladder — what to delete, what to add, what counts as
271	 * proof afterwards, what to say when it does not hold — must be exercised
272	 * without touching a kernel, so the only implementation production ever uses
273	 * (`iptablesHost` in worker/network.ts) is matched by an in-memory fake in
274	 * test/nat-sync.test.ts.
275	 */
276	export type NatHost = {
277	  /** Create the chain and the PREROUTING jump if absent. Must be idempotent. */
278	  ensureChain: () => Promise<void>;
279	  /** Raw `iptables -t nat -S <chain>` output. */
280	  listChain: () => Promise<string>;
281	  addRule: (r: NatRule) => Promise<void>;
282	  deleteRule: (r: NatRule) => Promise<void>;
283	};
284	
285	export type NatSyncResult = {
286	  added: number;
287	  deleted: number;
288	  /** Rules the chain is proven to hold. */
289	  verified: number;
290	  conflicts: NatConflict[];
291	  rejected: NatRejection[];
292	  /** Lines in our chain we could not parse; left alone, reported here. */
293	  unparsed: string[];
294	};
295	
296	/**
297	 * Reconcile the chain to `intent` and PROVE the result, or throw saying exactly
298	 * what is broken.
299	 *
300	 * Failure handling is deliberately two-phase. Individual `-A`/`-D` errors are
301	 * COLLECTED rather than thrown, so one bad rule can no longer abandon every
302	 * server after it in the list — that was the H5 blackhole. Then the chain is read
303	 * back and compared to the intent, and only that comparison decides success. A
304	 * rule that failed to add but turns out to be present anyway (a concurrent sync)
305	 * is not an error; a rule that "added fine" but is not in the chain is.
306	 */
307	export async function reconcileNatChain(
308	  host: NatHost,
309	  chain: string,
310	  intent: NatIntent
311	): Promise<NatSyncResult> {
312	  await host.ensureChain();
313	
314	  const current = parseChainRules(chain, await host.listChain());
315	  const plan = natReconcilePlan(intent.rules, current.rules);
316	  const errors: string[] = [];
317	
318	  // Delete first: frees a public port that is being reassigned to another guest
319	  // in the same pass, which would otherwise be an unresolvable conflict.
320	  let deleted = 0;
321	  for (const r of plan.toDelete) {
322	    try {
323	      await host.deleteRule(r);
324	      deleted++;
325	    } catch (e: any) {
326	      errors.push(`delete ${ruleText(r)}: ${String(e?.message ?? e).slice(0, 160)}`);
327	    }
328	  }
329	
330	  let added = 0;
331	  for (const r of plan.toAdd) {
332	    try {
333	      await host.addRule(r);
334	      added++;
335	    } catch (e: any) {
336	      errors.push(`add ${ruleText(r)}: ${String(e?.message ?? e).slice(0, 160)}`);
337	    }
338	  }
339	
340	  // The proof. Not "every call exited 0" — what the kernel actually holds now.
341	  const final = parseChainRules(chain, await host.listChain());
342	  const verdict = verifyNatChain(intent.rules, final.rules);
343	  if (!verdict.ok) {
344	    throw new Error(
345	      natFailureMessage({ chain, missing: verdict.missing, extra: verdict.extra, errors })
346	    );
347	  }
348	  if (errors.length) {
349	    // Every intended rule is present and no stray remains, so forwarding is
350	    // correct — but something errored on the way and that is not nothing.
351	    console.warn(`[nat] ${chain} reconciled, but iptables errored on the way: ${errors.join(" | ")}`);
352	  }
353	
354	  return {
355	    added,
356	    deleted,
357	    verified: final.rules.length,
358	    conflicts: intent.conflicts,
359	    rejected: intent.rejected,
360	    unparsed: final.unparsed,
361	  };
362	}
