126	  const byNode = new Map<string, typeof servers>();
127	  for (const s of servers) {
128	    const nodeId = (s as { nodeId?: string | null }).nodeId ?? primary?.id;
129	    if (!nodeId) continue; // no node row at all yet (fresh DB) — nothing to reconcile against
130	    if (!byNode.has(nodeId)) byNode.set(nodeId, []);
131	    byNode.get(nodeId)!.push(s);
132	  }
133	
134	  const results: NatSyncResult[] = [];
135	  const errors: string[] = [];
136	
137	  for (const node of nodes) {
138	    const nodeServers = byNode.get(node.id) ?? [];
139	    const intent = planNatRules(nodeServers as unknown as ForwardSource[]);
140	
141	    // Two data problems that used to be invisible because the old loop just
142	    // built whatever it was handed. Neither blocks this node's sync — the
143	    // ruleset installed is still verified end to end — but neither is
144	    // swallowed either.
145	    for (const c of intent.conflicts) {
146	      console.error(
147	        `[nat] ${node.name}: port collision: ${c.proto}/${c.dport} is claimed by ${c.winner} and also by ` +
148	          `${c.losers.join(", ")}. Only ${c.winner} is forwarded; the others get NOTHING on that port.`
149	      );
150	    }
151	    for (const r of intent.rejected) {
152	      console.error(`[nat] ${node.name}/${r.hostname}: no rule installed — ${r.reason}`);
153	    }
154	
155	    try {
156	      const result = await reconcileNatChain(natHostFor(node, node.natChain), node.natChain, intent);
157	      if (result.unparsed.length) {
158	        console.warn(
159	          `[nat] ${node.name}/${node.natChain} contains ${result.unparsed.length} rule(s) this engine did ` +
160	            `not write and will not touch: ${result.unparsed.slice(0, 5).join(" | ")}`
161	        );
162	      }
163	      console.log(
164	        `[nat] ${node.name}/${node.natChain} verified: ${result.verified} rule(s) present ` +
165	          `(+${result.added} / -${result.deleted})`
166	      );
167	      results.push(result);
168	    } catch (e: any) {
169	      // Collected, not thrown immediately — one node's failure (agent
170	      // unreachable, no token configured, a genuinely broken ruleset) must
171	      // never prevent every OTHER node's sync from being attempted.
172	      const msg = `${node.name}/${node.natChain}: ${String(e?.message ?? e)}`;
173	      console.error(`[nat] sync FAILED for ${msg}`);
174	      errors.push(msg);
175	    }
176	  }
177	
178	  if (errors.length) {
179	    throw new Error(`NAT sync failed for ${errors.length} node(s): ${errors.join(" | ")}`);
180	  }
181	  return results;
182	}
